import java.util.*;
import java.io.*;

class GraphPath {
    int N;
    List<List<Pair>> adj;

    static class Pair {
        int v, w;
        Pair(int v, int w) {
            this.v = v;
            this.w = w;
        }
    }

    GraphPath(int n) {
        N = n;
        adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }
    }

    void addEdge(int u, int v, int w) {
        adj.get(u).add(new Pair(v, w));
    }

    int[] getShortestDistances(int start, int end) {
        int[] dist = new int[N + 1];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[start] = 0;
        PriorityQueue<Pair> pq = new PriorityQueue<>((a, b) -> Integer.compare(b.w, a.w));
        pq.offer(new Pair(start, 0));
        while (!pq.isEmpty()) {
            Pair current = pq.poll();
            int u = current.v;
            int w = current.w;
            if (u == end) return dist;
            if (dist[u] < w) continue;
            for (Pair edge : adj.get(u)) {
                int v = edge.v;
                int w2 = w + edge.w;
                if (dist[v] > w2) {
                    dist[v] = w2;
                    pq.offer(new Pair(v, w2));
                }
            }
        }
        return dist;
    }
}

class GraphMST {
    int N;
    List<List<Pair>> edges;

    static class Pair {
        int v, w;
        Pair(int v, int w) {
            this.v = v;
            this.w = w;
        }
    }

    GraphMST(int n) {
        N = n;
        edges = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            edges.add(new ArrayList<>());
        }
    }

    void insert(int u, int v, int w) {
        edges.get(u).add(new Pair(v, w));
    }

    void computeMinimumSpanningTree(long[] totalCost) {
        int[] dist = new int[N + 1];
        boolean[] inMST = new boolean[N + 1];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[1] = 0;
        totalCost[0] = 0;
        PriorityQueue<Pair> pq = new PriorityQueue<>((a, b) -> Integer.compare(b.w, a.w));
        pq.offer(new Pair(1, 0));
        for (int i = 0; i < N; i++) {
            int u = -1;
            int minDist = Integer.MAX_VALUE;
            while (!pq.isEmpty()) {
                Pair top = pq.poll();
                u = top.v;
                if (!inMST[u]) break;
            }
            if (u == -1 || inMST[u]) break;
            inMST[u] = true;
            totalCost[0] += dist[u];
            for (Pair edge : edges.get(u)) {
                int v = edge.v;
                int w = edge.w;
                if (!inMST[v] && dist[v] > w) {
                    dist[v] = w;
                    pq.offer(new Pair(v, w));
                }
            }
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] V = new int[n];
        for (int i = 0; i < n; i++) {
            V[i] = sc.nextInt();
        }
        Arrays.sort(V);
        System.out.println(V[n / 2]);
        sc.close();
    }
}

